import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { parseEntries, humanTurns, assistantTextAfter, classificationLine } from '/home/user/Claudinite/engine/checks/helpers/session-transcript.mjs';

const dir = process.argv[2];
const files = readdirSync(dir).filter((f) => f.endsWith('.jsonl'));
let totalTurns = 0, classified = 0;
const hits = [];

function toolCallsBetween(entries, fromIndex) {
  let n = 0;
  for (let i = fromIndex + 1; i < entries.length; i += 1) {
    const e = entries[i];
    if (e.type === 'user' && !e.isMeta && !e.isSidechain) {
      const c = e.message?.content;
      const t = typeof c === 'string' ? c : null;
      if (t !== null && !t.trimStart().startsWith('<')) break;
    }
    if (e.type !== 'assistant') continue;
    const c = e.message?.content;
    if (!Array.isArray(c)) continue;
    for (const b of c) if (b?.type === 'tool_use') n += 1;
  }
  return n;
}

for (const f of files) {
  let entries;
  try { entries = parseEntries(readFileSync(join(dir, f), 'utf8')); } catch { continue; }
  const turns = humanTurns(entries);
  turns.forEach((turn, ti) => {
    totalTurns += 1;
    const reply = assistantTextAfter(entries, turn.index);
    const line = classificationLine(reply);
    if (!line) return;
    classified += 1;
    // strip the classification line; what's left?
    const rest = reply.replace(line, '').trim();
    const tools = toolCallsBetween(entries, turn.index);
    if (rest.length < 120 && tools === 0) {
      hits.push({ f, ti, ownerTurn: turn.text.slice(0, 200).replace(/\n/g, ' '), line: line.trim(), restLen: rest.length, rest: rest.slice(0, 200).replace(/\n/g, ' '), last: ti === turns.length - 1 });
    }
  });
}
console.log('files', files.length, 'ownerTurns', totalTurns, 'classifiedReplies', classified, 'bareStops', hits.length);
for (const h of hits) console.log(JSON.stringify(h));
