import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { parseEntries, classificationLine } from '/home/user/Claudinite/engine/checks/helpers/session-transcript.mjs';

const dir = process.argv[2];
const files = readdirSync(dir).filter((f) => f.endsWith('.jsonl'));
let soloBlocks = 0, soloIsLastAssistant = 0;
const samples = [];
for (const f of files) {
  let entries;
  try { entries = parseEntries(readFileSync(join(dir, f), 'utf8')); } catch { continue; }
  for (let i = 0; i < entries.length; i += 1) {
    const e = entries[i];
    if (e.type !== 'assistant') continue;
    const c = e.message?.content;
    if (!Array.isArray(c)) continue;
    const texts = c.filter((b) => b?.type === 'text').map((b) => b.text.trim());
    const hasTool = c.some((b) => b?.type === 'tool_use');
    for (const t of texts) {
      const line = classificationLine(t);
      if (!line) continue;
      if (t.replace(line, '').trim().length === 0) {
        soloBlocks += 1;
        // is anything after this entry in the file?
        const rest = entries.slice(i + 1);
        const lastOfSession = rest.every((x) => x.type !== 'assistant');
        if (lastOfSession) { soloIsLastAssistant += 1; samples.push({ f, line: line.trim(), hasTool }); }
      }
    }
  }
}
console.log('soloClassificationBlocks', soloBlocks, 'thatWereTheLastAssistantEntry', soloIsLastAssistant);
for (const s of samples.slice(0, 20)) console.log(JSON.stringify(s));
