cat > /tmp/claude-0/-home-user-Claudinite/e6579854-e1d6-5cb9-ad80-e5db59074eee/scratchpad/size.mjs <<'EOF'
import { readdirSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { parseEntries, humanTurns, assistantTextAfter, classificationLine, toolCalls } from '/home/user/Claudinite/engine/checks/helpers/session-transcript.mjs';

const dir = process.argv[2];
const files = readdirSync(dir).filter((f) => f.endsWith('.jsonl'));
const tally = { sessions: 0, noFirstTurn: 0, zeroTools: 0, c1: 0, c2: 0 };
const c1ex = [], c2ex = [];

for (const f of files) {
  let entries; try { entries = parseEntries(readFileSync(join(dir, f), 'utf8')); } catch { continue; }
  tally.sessions += 1;
  const first = humanTurns(entries)[0];
  if (!first) { tally.noFirstTurn += 1; continue; }
  const tools = toolCalls(entries).length;
  if (tools === 0) tally.zeroTools += 1;
  const reply = assistantTextAfter(entries, first.index);
  const line = classificationLine(reply);
  if (!line || tools !== 0) continue;
  tally.c1 += 1;
  c1ex.push({ f, owner: first.text.replace(/\s+/g, ' ').slice(0, 90), replyLen: reply.length });
  const rest = reply.replace(line, '').trim();
  if (rest.length < 200) { tally.c2 += 1; c2ex.push({ f, rest: rest.replace(/\s+/g, ' ').slice(0, 120) }); }
}
console.log(JSON.stringify(tally, null, 1));
console.log('--- C1 (first reply classified, session made zero tool calls) ---');
for (const e of c1ex.slice(0, 12)) console.log(JSON.stringify(e));
console.log('--- C2 (C1 + remainder < 200 chars) ---');
for (const e of c2ex.slice(0, 12)) console.log(JSON.stringify(e));
EOF
